package com.hms.social;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/social/connections") public class SocialConnectionController {private final TenantRepository tenants;private final SocialConnectionRepository connections;public SocialConnectionController(TenantRepository t,SocialConnectionRepository c){tenants=t;connections=c;} @GetMapping public List<SocialConnection> list(@PathVariable String tenantSlug){return connections.findAllByTenantIdOrderByPlatformAsc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public SocialConnection create(@PathVariable String tenantSlug,@Valid @RequestBody CreateSocialConnectionRequest r){return connections.save(new SocialConnection(tenant(tenantSlug),r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
